n_extract_scene.code:
const scene = input && typeof input === 'object' ? input : null;
if (!scene) return String(input || '');
const title = scene.title || '';
const raw = scene.content || '';
const saysM = raw.match(/^SAYS:\s*"?(.+?)"?\s*$/m);
const thinksM = raw.match(/^THINKS:\s*\*?(.+?)\*?\s*$/m);
const narrative = raw.replace(/^(SAYS|THINKS):.+$/gm, '').trim();
const says = saysM ? saysM[1].trim() : '';
const thinks = thinksM ? thinksM[1].trim() : '';
let prompt = title ? title + ': ' + narrative : narrative;
if (says) prompt += '. Speech bubble says: "' + says + '"';
if (thinks) prompt += '. Thought bubble thinks: "' + thinks + '"';
prompt += '. Style: bright flat cartoon illustration for a 5-year-old children picture book, cute anthropomorphic fox character, thick black outlines, bold pastel colours, big expressive eyes, simple clean background, speech bubble and thought bubble clearly visible, Aesop fable storybook art.';
return prompt;

